    sep_rows = [r for r, row in enumerate(grid) if 9 not in row]
    sep_cols = [c for c in range(w) if all(grid[r][c] != 9 for r in range(h))]
    wall, fill = grid[0][0], 9
    a = [[fill if grid[r][c] == wall else grid[r][c] for c in sep_cols] for r in sep_rows]
    # Trim borders with no colored marks; separator colors other than wall indicate marks.
    while a and all(x == fill for x in a[0]): a.pop(0)
    while a and all(x == fill for x in a[-1]): a.pop()
    if a:
        while all(row[0] == fill for row in a):
            for row in a: row.pop(0)
        while all(row[-1] == fill for row in a):
