def transform(grid):
    h,w=len(grid),len(grid[0])
    # Detect the room interior and separator line colors.
    interior=max(set(v for row in grid for v in row), key=lambda v:sum(row.count(v) for row in grid))
    # separator lines are the recurring rows/columns without interior color
    rs=[r for r,row in enumerate(grid) if interior not in row]
    cs=[c for c in range(w) if all(grid[r][c]!=interior for r in range(h))]
    # Grid lines form the encoded raster; wall-color intersections are blank pixels.
    wall=grid[0][0]
    a=[[interior if grid[r][c]==wall else grid[r][c] for c in cs] for r in rs]
    # collapse repeated adjacent rows and columns
    b=[]
    for row in a:
        if not b or row!=b[-1]: b.append(row)
    if b:
        keep=[j for j in range(len(b[0])) if j==0 or any(row[j]!=row[j-1] for row in b)]
        b=[[row[j] for j in keep] for row in b]
        while b and all(x==interior for x in b[0]): b.pop(0)
        while b and all(x==interior for x in b[-1]): b.pop()
        if b:
            while all(row[0]==interior for row in b):
                for row in b: row.pop(0)
            while all(row[-1]==interior for row in b):
                for row in b: row.pop()
    return b
